{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"private_outputs":true,"provenance":[],"authorship_tag":"ABX9TyMTUrjc6GqIeKEubYMiadZl"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":null,"metadata":{"id":"kb3Xf5OHkOLh"},"outputs":[],"source":["import requests\n","import json\n","import os\n","import time\n","from datetime import datetime\n","\n","# 1.\n","BASE_URL = \"https://hacker-news.firebaseio.com/v0\"\n","HEADERS = {\"User-Agent\": \"TrendPulse/1.0\"}\n","\n","#\n","CATEGORIES = {\n","    \"technology\": [\"AI\", \"software\", \"tech\", \"code\", \"computer\", \"data\", \"cloud\", \"API\", \"GPU\", \"LLM\"],\n","    \"worldnews\": [\"war\", \"government\", \"country\", \"president\", \"election\", \"climate\", \"attack\", \"global\"],\n","    \"sports\": [\"NFL\", \"NBA\", \"FIFA\", \"sport\", \"game\", \"team\", \"player\", \"league\", \"championship\"],\n","    \"science\": [\"research\", \"study\", \"space\", \"physics\", \"biology\", \"discovery\", \"NASA\", \"genome\"],\n","    \"entertainment\": [\"movie\", \"film\", \"music\", \"Netflix\", \"game\", \"book\", \"show\", \"award\", \"streaming\"]\n","}\n","\n","collected_data = []\n","category_counts = {cat: 0 for cat in CATEGORIES}\n","\n","def get_category(title):\n","    title_lower = title.lower()\n","    for category, keywords in CATEGORIES.items():\n","        for word in keywords:\n","            if word.lower() in title_lower:\n","                return category\n","    return None\n","\n","# folder creation\n","if not os.path.exists('data'):\n","    os.makedirs('data')\n","\n","try:\n","    # Step 1: top story id's\n","    print(\"Fetching top stories...\")\n","    response = requests.get(f\"{BASE_URL}/topstories.json\", headers=HEADERS)\n","    story_ids = response.json()[:500]\n","\n","    # Step 2: each story explain\n","    for cat_name in CATEGORIES.keys():\n","        print(f\"Processing category: {cat_name}...\")\n","\n","        for s_id in story_ids:\n","            # each categories maximam 25 story only\n","            if category_counts[cat_name] >= 25:\n","                break\n","\n","            try:\n","                item_res = requests.get(f\"{BASE_URL}/item/{s_id}.json\", headers=HEADERS)\n","                story = item_res.json()\n","\n","                if not story or 'title' not in story:\n","                    continue\n","\n","                assigned_cat = get_category(story['title'])\n","\n","                # if story categories mach save tha data\n","                if assigned_cat == cat_name:\n","                    story_info = {\n","                        \"post_id\": story.get(\"id\"),\n","                        \"title\": story.get(\"title\"),\n","                        \"category\": assigned_cat,\n","                        \"score\": story.get(\"score\"),\n","                        \"num_comments\": story.get(\"descendants\", 0),\n","                        \"author\": story.get(\"by\"),\n","                        \"collected_at\": datetime.now().strftime(\"%Y-%m-%d %H:%M:%S\")\n","                    }\n","                    collected_data.append(story_info)\n","                    category_counts[cat_name] += 1\n","\n","            except Exception as e:\n","                print(f\"Error fetching story {s_id}: {e}\")\n","                continue\n","\n","        #  categories 2 sceond time\n","        time.sleep(2)\n","\n","    # 3. load to JSON file\n","    date_str = datetime.now().strftime(\"%Y%m%d\")\n","    file_path = f\"data/trends_{date_str}.json\"\n","\n","    with open(file_path, 'w') as f:\n","        json.dump(collected_data, f, indent=4)\n","\n","    print(f\"Collected {len(collected_data)} stories. Saved to {file_path}\")\n","\n","except Exception as e:\n","    print(f\"An error occurred: {e}\")"]},{"cell_type":"code","source":["import pandas as pd\n","import os\n","from datetime import datetime\n","\n","# 1. Load the JSON File\n","\n","date_str = datetime.now().strftime(\"%Y%m%d\")\n","input_file = f\"data/trends_{date_str}.json\"\n","output_file = \"data/trends_clean.csv\"\n","\n","try:\n","    if not os.path.exists(input_file):\n","        print(f\"Error: {input_file} NO file!\")\n","    else:\n","        # load the JSON file\n","        df = pd.read_json(input_file)\n","        print(f\"Loaded {len(df)} stories from {input_file}\")\n","\n","        # 2.Clean the Data\n","\n","        # Remove Duplicates\n","        df = df.drop_duplicates(subset=['post_id'])\n","        print(f\"After removing duplicates: {len(df)}\")\n","\n","        # Remove Nulls\n","        df = df.dropna(subset=['post_id', 'title', 'score'])\n","        print(f\"After removing nulls: {len(df)}\")\n","\n","        # Fix Data Types\n","        df['score'] = df['score'].astype(int)\n","        df['num_comments'] = df['num_comments'].fillna(0).astype(int)\n","\n","        # Low Quality Filter\n","        df = df[df['score'] >= 5]\n","        print(f\"After removing low scores: {len(df)}\")\n","\n","        #  Spaces remove Whitespace on title\n","        df['title'] = df['title'].str.strip()\n","\n","        # 3. Save as CSV\n","        df.to_csv(output_file, index=False)\n","        print(f\"Saved {len(df)} rows to {output_file}\")\n","\n","        # categories wase Summary\n","        print(\"\\nStories per category:\")\n","        print(df['category'].value_counts())\n","\n","except Exception as e:\n","    print(f\"An error occurred: {e}\")"],"metadata":{"id":"5kXs0R-dkWOg"},"execution_count":null,"outputs":[]},{"cell_type":"code","source":["import pandas as pd\n","import numpy as np\n","\n","# 1.Load and Explore\n","try:\n","    file_path = \"data/trends_clean.csv\"\n","    df = pd.read_json(file_path) if file_path.endswith('.json') else pd.read_csv(file_path)\n","\n","    print(f\"Loaded data: {df.shape}\")\n","    print(\"\\nFirst 5 rows:\")\n","    print(df.head())\n","\n","\n","    avg_score = df['score'].mean()\n","    avg_comments = df['num_comments'].mean()\n","    print(f\"\\nAverage score   : {avg_score:.2f}\")\n","    print(f\"Average comments: {avg_comments:.2f}\")\n","\n","    # 2. Basic Analysis with NumPy\n","    print(\"\\n--- NumPy Stats ---\")\n","\n","    scores = df['score'].to_numpy()\n","\n","    print(f\"Mean score   : {np.mean(scores):.2f}\")\n","    print(f\"Median score : {np.median(scores):.2f}\")\n","    print(f\"Std deviation: {np.std(scores):.2f}\")\n","    print(f\"Max score    : {np.max(scores)}\")\n","    print(f\"Min score    : {np.min(scores)}\")\n","\n","    # story categories\n","    top_category = df['category'].value_counts().idxmax()\n","    cat_count = df['category'].value_counts().max()\n","    print(f\"Most stories in: {top_category} ({cat_count} stories)\")\n","\n","    # story comments more\n","    max_comments_idx = df['num_comments'].idxmax()\n","    top_story = df.loc[max_comments_idx]\n","    print(f\"Most commented story: \\\"{top_story['title']}\\\" — {top_story['num_comments']} comments\")\n","\n","    # 3. Add New Columns\n","\n","    # Engagement:Division by zero రాకుండా score + 1\n","    df['engagement'] = df['num_comments'] / (df['score'] + 1)\n","\n","    # Is Popular: score True,  False\n","    df['is_popular'] = df['score'] > avg_score\n","\n","    # 4. Save the Result\n","    output_file = \"data/trends_analysed.csv\"\n","    df.to_csv(output_file, index=False)\n","    print(f\"\\nSaved to {output_file}\")\n","\n","except FileNotFoundError:\n","    print(\"Error: 'data/trends_clean.csv' ఫైల్ దొరకలేదు. ముందు Task 2 పూర్తి చేయండి.\")\n","except Exception as e:\n","    print(f\"An error occurred: {e}\")"],"metadata":{"id":"CgTbbXM_klgo"},"execution_count":null,"outputs":[]},{"cell_type":"code","source":[],"metadata":{"id":"V-yLkgWHkVYd"},"execution_count":null,"outputs":[]}]}